#include "../src/ppc_math.h"
#include "../src/physics.h"
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static double value(uint64_t b){double x;memcpy(&x,&b,8);return x;}
static uint64_t bits(double x){uint64_t b;memcpy(&b,&x,8);return b;}
static void exact(double actual,uint64_t expected,unsigned row,const char*field){if(bits(actual)!=expected){fprintf(stderr,"row %u %s actual=%016llx expected=%016llx\n",row,field,(unsigned long long)bits(actual),(unsigned long long)expected);exit(1);}}
int main(int argc,char**argv){const char*physics=argc>1?argv[1]:"tests/physics_hex_vectors.csv";const char*asinfile=argc>2?argv[2]:"tests/asin_hex_vectors.csv";FILE*f=fopen(physics,"r");if(!f)return 2;char line[1024];fgets(line,sizeof line,f);unsigned row=0;while(fgets(line,sizeof line,f)){uint64_t a[12];char*p=line;for(int i=0;i<12;i++){a[i]=strtoull(p,&p,16);if(i<11&&*p++!=',')return 2;}row++;exact(astro_ppc_cos(value(a[5])),a[6],row,"cos");exact(astro_ppc_sin(value(a[5])),a[7],row,"sin");AstroVelocity v={value(a[0]),value(a[1])};astro_vector_make(&v,value(a[2]),value(a[3]));exact(v.x,a[8],row,"make.x");exact(v.y,a[9],row,"make.y");v=(AstroVelocity){value(a[8]),value(a[9])};astro_vector_slow(&v,value(a[4]));exact(v.x,a[10],row,"slow.x");exact(v.y,a[11],row,"slow.y");}fclose(f);if(row!=1000)return 2;f=fopen(asinfile,"r");if(!f)return 2;fgets(line,sizeof line,f);unsigned n=0;while(fgets(line,sizeof line,f)){char*p=line;uint64_t in=strtoull(p,&p,16),out=strtoull(p+1,&p,16);exact(astro_ppc_asin(value(in)),out,++n,"asin");}fclose(f);if(n!=4096)return 2;
f=fopen(argc>3?argv[3]:"tests/atan_hex_vectors.csv","r");if(!f)return 2;fgets(line,sizeof line,f);unsigned na=0;while(fgets(line,sizeof line,f)){char*p=line;uint64_t in=strtoull(p,&p,16),out=strtoull(p+1,&p,16);exact(astro_ppc_atan(value(in)),out,++na,"atan");}fclose(f);if(na!=4096)return 2;exact(astro_ppc_asin(value(UINT64_C(0x7ff8000000001234))),UINT64_C(0x7ff8000000000022),0,"asin.NaN");exact(astro_ppc_asin(value(UINT64_C(0xfff8000000001234))),UINT64_C(0xfff8000000000022),0,"asin.-NaN");if(astro_ppc_i32(value(UINT64_C(0x7ff8000000000000)))!=INT32_MIN||astro_ppc_i32(2147483648.)!=INT32_MAX||astro_ppc_i32(-2147483649.)!=INT32_MIN||astro_ppc_i32(1.9)!=1||astro_ppc_i32(-1.9)!=-1)return 1;exact(astro_ppc_asin(2),UINT64_C(0x7ff8000000000022),0,"asin.domain");printf("PASS: %u native PPC vector/trig and %u asin and %u atan raw IEEE fixtures\n",row,n,na);return 0;}
